begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select set_config('request.jwt.claim.role','service_role',true);
insert into auth.users(id,email,raw_user_meta_data) values('b3600000-0000-4000-8000-000000000001','expiry-queue@example.test','{"full_name":"Expiry Queue"}');
insert into public.fare_revisions(id,custom_fare_centavos,reason) values('b3610000-0000-4000-8000-000000000001',10000,'Expiry queue fixture');
insert into public.cancellation_policies(id,terms) values('b3610000-0000-4000-8000-000000000002','Expiry queue fixture');
insert into public.bookings(id,tourist_id,fare_revision_id,cancellation_policy_id,quoted_amount_centavos,payment_method,payment_status,pickup_address,pickup_latitude,pickup_longitude,pickup_code_hash)
values('b3620000-0000-4000-8000-000000000001','b3600000-0000-4000-8000-000000000001','b3610000-0000-4000-8000-000000000001','b3610000-0000-4000-8000-000000000002',10000,'paymongo','unpaid','Queue fixture',14.9571,120.9188,crypt('1234',gen_salt('bf')));
insert into public.payments(id,booking_id,provider,provider_mode,provider_checkout_id,amount_centavos,status) values('b3630000-0000-4000-8000-000000000001','b3620000-0000-4000-8000-000000000001','paymongo','test','cs_expiry_queue',10000,'checkout_created');
update public.bookings set payment_expires_at=now()-interval '1 minute' where id='b3620000-0000-4000-8000-000000000001';
select public.expire_unpaid_bookings();
select is((select count(*)::integer from public.checkout_expiry_requests where payment_id='b3630000-0000-4000-8000-000000000001'),1,'local expiry atomically enqueues provider expiry');
select is(has_function_privilege('authenticated','public.claim_checkout_expiries(uuid,integer)','execute'),false,'clients cannot claim expiry work');
select is((select count(*)::integer from public.claim_checkout_expiries('b3640000-0000-4000-8000-000000000001',20)),1,'worker claims one job');
select is((select count(*)::integer from public.claim_checkout_expiries('b3640000-0000-4000-8000-000000000002',20)),0,'active lease prevents a second worker claim');
select is(public.finish_checkout_expiry('b3630000-0000-4000-8000-000000000001','b3640000-0000-4000-8000-000000000002','expired'),false,'wrong worker cannot acknowledge expiry');
select is(public.finish_checkout_expiry('b3630000-0000-4000-8000-000000000001','b3640000-0000-4000-8000-000000000001','processing'),true,'ongoing payment is deferred rather than marked expired');
select is((select state from public.checkout_expiry_requests where payment_id='b3630000-0000-4000-8000-000000000001'),'queued','processing response remains retryable');
update public.checkout_expiry_requests set next_attempt_at=now() where payment_id='b3630000-0000-4000-8000-000000000001';
select * from public.claim_checkout_expiries('b3640000-0000-4000-8000-000000000002',20);
update public.checkout_expiry_requests set claim_until=now()-interval '1 second' where payment_id='b3630000-0000-4000-8000-000000000001';
select is((select count(*)::integer from public.claim_checkout_expiries('b3640000-0000-4000-8000-000000000003',20)),1,'interrupted worker lease can be reclaimed');
select is(public.finish_checkout_expiry('b3630000-0000-4000-8000-000000000001','b3640000-0000-4000-8000-000000000003','expired'),true,'current worker can record confirmed provider expiry');
select is((select state from public.checkout_expiry_requests where payment_id='b3630000-0000-4000-8000-000000000001'),'expired','confirmed expiry is terminal');
select is((select count(*)::integer from cron.job where jobname='expire-paymongo-provider-checkouts'),1,'provider expiry dispatcher is scheduled');
select is(public.invoke_checkout_expiry_worker(),null::bigint,'missing environment Vault configuration makes no outbound request');
select * from finish();rollback;
